//! The sanitizer (`WP_Theme_JSON::sanitize`); every expected value was produced by WordPress;
//! the values WordPress 7.2 changed are 7.2-RC2's.
//!
//! Generated by `.superpowers/gen_sanitize.py` from the release's own code; edit the generator, not the cases.

mod support;

use speedyspec_wp_theme_json::sanitize::{ValidNames, sanitize};
use support::{assert_php_eq, json};

fn valid(blocks: &[&str], variations: &[(&str, Vec<&str>)]) -> ValidNames {
    ValidNames::new(
        blocks.iter().map(|b| (*b).to_owned()).collect(),
        speedyspec_wp_theme_json_contracts::schema::element_names(),
        variations
            .iter()
            .map(|(b, v)| ((*b).to_owned(), v.iter().map(|x| (*x).to_owned()).collect()))
            .collect(),
    )
}

#[test]
fn top_level_keys_filtered() {
    let actual = sanitize(
        &json(r##"{"version":3,"bogus":1,"title":"T","blockTypes":["core/a"],"patterns":["p"]}"##),
        &valid(&["core/group"], &[]),
    );
    assert_php_eq(
        &actual,
        &json(r##"{"blockTypes":["core/a"],"patterns":["p"],"title":"T","version":3}"##),
    );
}

#[test]
fn viewport_sanitized() {
    let actual = sanitize(
        &json(r##"{"version":3,"settings":{"viewport":{"mobile":" 30em ","tablet":"20em"}}}"##),
        &valid(&["core/group"], &[]),
    );
    assert_php_eq(
        &actual,
        &json(r##"{"settings":{"viewport":{"mobile":"30em"}},"version":3}"##),
    );
}

