#[test]
fn var_format() {
    let actual = sanitize(
        &json(
            r##"{"version":3,"settings":{"custom":{"a":"var:preset|color|x","b":{"c":"var:custom|d"}}},"styles":{"color":{"text":"var:preset|color|red"},"spacing":{"padding":{"top":"var:preset|spacing|20"}}}}"##,
        ),
        &valid(&["core/group"], &[]),
    );
    assert_php_eq(
        &actual,
        &json(
            r##"{"settings":{"custom":{"a":"var(--wp--preset--color--x)","b":{"c":"var(--wp--custom--d)"}}},"styles":{"color":{"text":"var(--wp--preset--color--red)"},"spacing":{"padding":{"top":"var(--wp--preset--spacing--20)"}}},"version":3}"##,
        ),
    );
}

