#[test]
fn variations_filtered() {
    let actual = sanitize(
        &json(
            r##"{"version":3,"styles":{"blocks":{"core/group":{"variations":{"a":{"color":{"text":"red"},"@mobile":{"color":{"text":"m"},"blocks":{"core/group":{"color":{"text":"n"}}}},"blocks":{"core/group":{"color":{"text":"x"}}},"elements":{"link":{"color":{"text":"l"}}}},"b":{"color":{"text":"blue"}}}}}}}"##,
        ),
        &valid(&["core/group"], &[("core/group", vec!["a"])]),
    );
    assert_php_eq(
        &actual,
        &json(
            r##"{"styles":{"blocks":{"core/group":{"variations":{"a":{"@mobile":{"color":{"text":"m"}},"blocks":{"core/group":{"color":{"text":"x"}}},"color":{"text":"red"},"elements":{"link":{"color":{"text":"l"}}}}}}}},"version":3}"##,
        ),
    );
}

#[test]
fn variations_order_quirk() {
    let actual = sanitize(
        &json(
            r##"{"version":3,"styles":{"blocks":{"core/a":{"variations":{"v":{"@mobile":{"blocks":{"core/b":{"variations":{"w":{"color":{"text":"1"}}}}}}}}},"core/b":{"variations":{"w":{"@mobile":{"blocks":{"core/a":{"variations":{"v":{"color":{"text":"2"}}}}}}}}}}}}"##,
        ),
        &valid(
            &["core/a", "core/b"],
            &[("core/a", vec!["v"]), ("core/b", vec!["w"])],
        ),
    );
    assert_php_eq(&actual, &json(r##"{"version":3}"##));
}

