#[test]
fn presets_without_a_scalar_slug_dropped() {
    let actual = sanitize(
        &json(
            r##"{"version":3,"settings":{"color":{"palette":[{"slug":"a","color":"#000"},"x",{"slug":["b"],"color":"#111"},{"color":"#222"},{"slug":3,"color":"#333"}]},"blocks":{"core/group":{"color":{"palette":{"theme":[{"slug":"c"},5],"custom":"nope"}}}}}}"##,
        ),
        &valid(&["core/group"], &[]),
    );
    assert_php_eq(
        &actual,
        &json(
            r##"{"settings":{"blocks":{"core/group":{"color":{"palette":{"custom":"nope","theme":[{"slug":"c"}]}}}},"color":{"palette":[{"color":"#000","slug":"a"},{"color":"#222"},{"color":"#333","slug":3}]}},"version":3}"##,
        ),
    );
}
